SINA_SMART["cellbio1-cytoskeleton"] = {"lecture":"cellbio1-cytoskeleton","title":"The cytosol and the cytoskeleton","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"cellbio1-cytoskeleton:e0","text":"Cytosol ~70% water; inclusions: proteasomes, lipid droplets, glycogen.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e1","text":"Actin 5-8 nm; intermediate filaments 8-10 nm; microtubules 20-30 nm.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e2","text":"G-actin (ATP) → F-actin, nucleated by ARP2/3.","topic":"Actin microfilaments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e3","text":"Actin: cortex, microvilli, contractile ring, migration, diapedesis; myosin II contraction.","topic":"Actin microfilaments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e4","text":"Small G proteins: Ras, Rac, Rho, Cdc42, Rab, Ran.","topic":"Actin microfilaments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e5","text":"Microtubules: α/β-tubulin + GTP, 13 protofilaments on γ-TuRC, MAP2 stabilises.","topic":"Microtubules","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e6","text":"Kinesin and dynein carry cargo on microtubules.","topic":"Microtubules","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e7","text":"MT roles: spindle, cilia, flagella, centrioles, axons.","topic":"Microtubules","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e8","text":"Colchicine and vinca alkaloids block polymerisation; taxol blocks depolymerisation.","topic":"Microtubules","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-cytoskeleton:e9","text":"IF: stable; lamins; cytokeratin (carcinoma), vimentin (sarcoma), desmin (muscle), GFAP (glioma).","topic":"Intermediate filaments","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1lfei6":"a","1l1ottn":"a","1c9te8o":"a","1jsohbt":"a","lu58tq":"a","b7coz8":"a","1v6x4c9":"a","ms0u65":"a","19fxelq":"a","4iauu9":"a","6nkssi":"a","uwp87i":"a","18eczqj":"a","1bjkp6s":"a","1llgqgp":"a","j42rne":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"cellbio1-cytoskeleton:e0":{"s":0,"u":["Cytosol ~70% water; inclusions: proteasomes, lipid droplets, glycogen.","The cytosol (hyaloplasm) is ~ 70% water with small molecules (ions, gases, glucose, amino acids, fatty acids, urea, glycerol), macromolecules (proteins, lipids, carbohydrates, RNA) and inert inclusions (proteasomes, lipid droplets, glycogen rosettes)."],"dp":[]},"cellbio1-cytoskeleton:e1":{"s":0,"u":["Actin 5-8 nm; intermediate filaments 8-10 nm; microtubules 20-30 nm.","Three types: actin microfilaments (5-8 nm) , intermediate filaments (8-10 nm) , microtubules (20-30 nm) ."],"dp":[{"h":"Why intermediate filaments help pathologists","t":"Each tissue makes its own type of intermediate filament, and tumour cells usually keep that type even when they look nothing like the original tissue. Staining a tumour for cytokeratin, vimentin or GFAP therefore reveals whether it arose from epithelium, connective tissue or glia, which guides treatment. Source: the lecture's intermediate filament families slide."}]},"cellbio1-cytoskeleton:e2":{"s":1,"u":["G-actin (ATP) → F-actin, nucleated by ARP2/3.","G-actin (globular monomer with an ATP groove) assembles into F-actin , two twisted chains, nucleated by ARP2/3 .","Polymerisation rises with the concentration of G-actin-ATP and reverses when it falls."],"dp":[]},"cellbio1-cytoskeleton:e3":{"s":1,"u":["Actin: cortex, microvilli, contractile ring, migration, diapedesis; myosin II contraction.","Roles : cell cortex under the membrane (3D shape), cytoplasmic currents, microvilli (intestine, kidney), endo/exocytosis vesicle traffic, the contractile ring of cytokinesis, diapedesis of white cells and cell migration (macrophages).","Associated proteins: ARP2/3 (assembly), CapZ (stops polymerisation), tropomyosin (protects), troponin, myosin II (muscle contraction), severin (cuts), myosin I (links cortex to membrane: spectrin in red cells, dystrophin in muscle), crosslinkers (fimbrin, filamin, actinin)."],"dp":[]},"cellbio1-cytoskeleton:e4":{"s":1,"u":["Small G proteins: Ras, Rac, Rho, Cdc42, Rab, Ran.","Small G proteins (GTP active, GDP inactive): Ras (signalling), Rac (migration), Rho (tension), Cdc42 (migration, polarity, cycle), Rab (vesicle traffic), Ran (nuclear transport)."],"dp":[]},"cellbio1-cytoskeleton:e5":{"s":2,"u":["Microtubules: α/β-tubulin + GTP, 13 protofilaments on γ-TuRC, MAP2 stabilises.","α- and β-tubulin form dimers (with GTP), dimers form protofilaments, and 13 protofilaments assemble on the γ-TuRC (γ-tubulin ring complex) into a tube, stabilised by MAP2 .","Polymerisation depends on free GTP-tubulin; normally balanced; imbalance causes collapse (' catastrophe ': fewer GTP-tubulins, loss of MAP2, tension)."],"dp":[]},"cellbio1-cytoskeleton:e6":{"s":2,"u":["Kinesin and dynein carry cargo on microtubules.","Associated proteins: γ-TuRC, MAP2, kinetochore (attaches chromosomes to the spindle), and motor proteins converting ATP into movement: kinesin and dynein carrying cargo along microtubules."],"dp":[]},"cellbio1-cytoskeleton:e7":{"s":2,"u":["MT roles: spindle, cilia, flagella, centrioles, axons.","Roles : shape, organelle transport, cilia and flagella , axons, centrioles , the mitotic spindle , diapedesis and migration."],"dp":[]},"cellbio1-cytoskeleton:e8":{"s":2,"u":["Colchicine and vinca alkaloids block polymerisation; taxol blocks depolymerisation.","Drugs : colchicine binds free tubulin and blocks polymerisation (antimitotic); vinca alkaloids ( vinblastine, vincristine ) and podophyllin are antimitotics in chemotherapy; taxol (paclitaxel, from yew; breast cancer) instead prevents depolymerisation of the spindle, blocking division."],"dp":[{"h":"Why two opposite drugs both stop cancer cells","t":"The mitotic spindle works only if microtubules keep growing and shrinking to pull chromosomes apart. Colchicine and vinca alkaloids stop them growing; taxol freezes them so they cannot shrink. Either way the spindle cannot do its job, the cell is stuck in mitosis, and fast-dividing cancer cells are hit hardest. Source: the lecture's pharmacological effects on microtubules."}]},"cellbio1-cytoskeleton:e9":{"s":3,"u":["IF: stable; lamins; cytokeratin (carcinoma), vimentin (sarcoma), desmin (muscle), GFAP (glioma).","Families used in immunohistochemistry to identify tumour origin: cytokeratins (epithelia → carcinomas), desmin (muscle), vimentin (connective tissue → sarcomas), neurofilaments (neurons → neuroblastoma), GFAP (glial fibrillary acidic protein; glial cells → gliomas).","Stable (no cycles of polymerisation), the true skeleton maintaining cell shape; lamins A, B, C form the nuclear lamina reinforcing the nuclear envelope."],"dp":[]}},"meta":{"1lfei6":{"a":"recall","vg":"cellbio1-cytoskeleton:e0/recall/1"},"1l1ottn":{"a":"recall","vg":"cellbio1-cytoskeleton:e1/recall/1"},"1c9te8o":{"a":"recall","vg":"cellbio1-cytoskeleton:e1/recall/2"},"1jsohbt":{"a":"recall","vg":"cellbio1-cytoskeleton:e2/recall/1"},"lu58tq":{"a":"recall","vg":"cellbio1-cytoskeleton:e2/recall/2"},"b7coz8":{"a":"recall","vg":"cellbio1-cytoskeleton:e1/recall/3"},"1v6x4c9":{"a":"recall","vg":"cellbio1-cytoskeleton:e4/recall/1"},"ms0u65":{"a":"recall","vg":"cellbio1-cytoskeleton:e5/recall/1"},"19fxelq":{"a":"recall","vg":"cellbio1-cytoskeleton:e6/recall/1"},"4iauu9":{"a":"recall","vg":"cellbio1-cytoskeleton:e8/recall/1"},"6nkssi":{"a":"recall","vg":"cellbio1-cytoskeleton:e8/recall/2"},"uwp87i":{"a":"recall","vg":"cellbio1-cytoskeleton:e1/recall/4"},"18eczqj":{"a":"recall","vg":"cellbio1-cytoskeleton:e9/recall/1"},"1bjkp6s":{"a":"recall","vg":"cellbio1-cytoskeleton:e9/recall/2"},"1llgqgp":{"a":"recall","vg":"cellbio1-cytoskeleton:e9/recall/3"},"j42rne":{"a":"relationship","vg":"cellbio1-cytoskeleton:e1/relationship/1"}},"explRev":"76c2e4de20d9"};
